const incoming = $input.first().json;
const body = incoming.body ?? incoming;
const phone = String(body.phone ?? '').replace(/\D/g, '');
const hasPhone = phone.length >= 8;
const booked = body.booked === true || String(body.status ?? '').toUpperCase() === 'BOOKED';
const optedOut = body.optOut === true;
const permitted = body.contactAllowed === true;
const eligible = hasPhone && permitted && !booked && !optedOut;
let skipReason = '';
if (!hasPhone) skipReason = 'MISSING_OR_INVALID_PHONE';
else if (booked) skipReason = 'ALREADY_BOOKED';
else if (optedOut) skipReason = 'OPTED_OUT';
else if (!permitted) skipReason = 'CONTACT_PERMISSION_NOT_CONFIRMED';
return [{ json: {
  leadKey: phone ? `phone:${phone}` : null,
  name: String(body.name ?? '').trim(),
  phoneDigits: phone,
  project: String(body.project ?? '').trim(),
  source: String(body.source ?? 'unknown').trim(),
  createdAt: body.createdAt ?? new Date().toISOString(),
  firstCallDueAt: new Date(Date.now() + 60 * 1000).toISOString(),
  status: booked ? 'BOOKED' : (eligible ? 'NEW' : 'SUPPRESSED'),
  callAttemptCount: Number(body.callAttemptCount ?? 0),
  contactAllowed: permitted, optOut: optedOut, booked,
  callEligible: eligible, skipReason,
  nextStep: eligible ? 'UPSERT_AND_DISPATCH_CALL_BY_ONE_MINUTE_TARGET' : 'LOG_SUPPRESSION'
} }];

const incoming = $input.first().json;
const body = incoming.body ?? incoming;
const attempts = Math.max(1, Number(body.callAttemptCount ?? 1));
const answered = body.answered === true;
const noAnswer = body.answered === false;
const visitBooked = body.visitBooked === true;
const within30Days = Number(body.daysToPurchase ?? 999) <= 30;
const interested = body.interested === true;
const months = Number(body.monthsToPurchase ?? 99);
const needsRetry = noAnswer && attempts < 3;
const temperature = visitBooked || within30Days ? 'HOT' : (interested && months <= 3 ? 'WARM' : 'COLD');
const status = needsRetry ? 'CALL_RETRY_PENDING' : (noAnswer ? 'COLD' : temperature);
const nextStep = needsRetry ? 'RETRY_AFTER_TWO_HOURS' : (noAnswer ? 'STOP_CALLS_AFTER_THIRD_MISS' : (temperature === 'HOT' ? 'ALERT_SALES_SAME_DAY' : (temperature === 'WARM' ? 'SCHEDULE_WARM_FOLLOWUP' : 'COLD_NO_CALLS')));
return [{ json: {
  leadKey: body.leadKey ?? null,
  callAttemptCount: attempts,
  answered,
  project: body.project ?? null,
  budget: body.budget ?? null,
  size: body.size ?? null,
  purpose: body.purpose ?? null,
  timeline: body.timeline ?? null,
  callSummary: body.callSummary ?? '',
  visitBooked,
  temperature: noAnswer && attempts >= 3 ? 'COLD' : temperature,
  status,
  score: null,
  scoreNote: 'Business scoring rubric must be configured before a numeric score is assigned.',
  needsRetry,
  nextCallDueAt: needsRetry ? new Date(Date.now() + 2 * 60 * 60 * 1000).toISOString() : null,
  nextStep
} }];

const incoming = $input.first().json;
const body = incoming.body ?? incoming;
const needsHuman = body.priceNegotiation === true || body.humanRequested === true;
const bookVisit = body.bookVisit === true;
const action = needsHuman ? 'HUMAN_HANDOFF' : (bookVisit ? 'BOOK_SITE_VISIT' : 'ANSWER_OR_SHARE_APPROVED_CONTENT');
const holdUntil = new Date(Date.now() + 30 * 60 * 1000).toISOString();
return [{ json: {
  leadKey: body.leadKey ?? null,
  language: ['hi','hindi'].includes(String(body.language ?? '').toLowerCase()) ? 'Hindi' : 'English',
  requestedAction: action,
  holdUntil,
  historyLookup: 'CONNECT_LEAD_HISTORY_LOOKUP_BEFORE_REPLY',
  responseTargetSeconds: '10-20 (source target; not measured)',
  nextStep: action
} }];

const incoming = $input.first().json;
const body = incoming.body ?? incoming;
const temperature = String(body.temperature ?? '').toUpperCase();
let nextStep = 'READ_DUE_LEADS_AND_BUILD_DAILY_COUNTS';
if (temperature === 'HOT') nextStep = 'ALERT_SALES_AND_STOP_NURTURE';
if (temperature === 'WARM') nextStep = 'CHECK_DUE_DAY_2_5_10_MESSAGE_OR_SCHEDULED_CALL';
if (temperature === 'COLD') nextStep = 'NO_CALLS_MONTHLY_MESSAGE_ONLY_IF_ELIGIBLE';
return [{ json: {
  leadKey: body.leadKey ?? null,
  temperature: temperature || 'REPORT_RUN',
  nextStep,
  reportTime: '13:00 instance timezone; confirm business timezone',
  reportMetrics: ['leads','calls','siteVisits']
} }];
